PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person 
       (COALESCE(?dbpBirth, ?dboBirth) AS ?birthDate) 
       (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
WHERE {
  VALUES ?person { dbr:Martino_Finotto dbr:Franklin_Edson }

  OPTIONAL { ?person dbp:birthDate ?dbpBirth . }
  OPTIONAL { ?person dbo:birthDate ?dboBirth . }

  OPTIONAL { ?person dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?person dbo:deathDate ?dboDeath . }
}
LIMIT 100

